import {
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  check,
} from 'drizzle-orm/pg-core'
import { sql } from 'drizzle-orm'
import { user } from '../auth/auth.schema'
import { timestamps, uuidv7PrimaryKey } from '../_shared/columns'

/** One company employee, retained when login access is suspended or employment ends. A person keeps the same record when restored. */
export const employee = pgTable(
  'employee',
  {
    /** Time-ordered employee identifier generated by PostgreSQL 18. */
    id: uuidv7PrimaryKey(),
    /** Immutable login username, normalized to lowercase. The column name is retained for existing records. */
    code: text('code').notNull(),
    /** Exactly one login identity per employee; deletion is restricted to preserve employment history. */
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'restrict' }),
    /** Employee's company-recorded full name, independent from their auth display name. */
    fullName: text('full_name').notNull(),
    /** Optional real contact email; null when the employee has no email. This is never a synthetic auth identifier. */
    contactEmail: text('contact_email'),
    jobTitle: text('job_title'),
    phone: text('phone'),
    /** Active employment permits login; inactive records remain available for restoration. */
    status: text('status').notNull().default('active'),
    ...timestamps(),
  },
  (table) => [
    uniqueIndex('employee_code_unique').on(table.code),
    uniqueIndex('employee_one_account').on(table.userId),
    check(
      'employee_status_valid',
      sql`${table.status} in ('active', 'inactive')`,
    ),
    check(
      'employee_code_normalized',
      sql`${table.code} = lower(${table.code}) and ${table.code} ~ '^[a-z0-9][a-z0-9._-]{2,31}$'`,
    ),
  ],
)

/** One current activation or reset challenge per account. Reissuing replaces the previous challenge atomically. */
export const accountSetup = pgTable(
  'account_setup',
  {
    /** Target account; a primary key prevents multiple live challenges for the same employee. */
    userId: text('user_id')
      .primaryKey()
      .references(() => user.id, { onDelete: 'restrict' }),
    /** SHA-256 digest of a random 12-character one-time code; the raw code is returned only once. */
    codeHash: text('code_hash').notNull().unique(),
    /** Separates initial activation from resetting an existing password. */
    purpose: text('purpose').notNull(),
    /** UTC expiry, enforced again in the transaction that consumes the challenge. */
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    /** Account that authorized this challenge; null for operator-only bootstrap or owner recovery. */
    issuedBy: text('issued_by').references(() => user.id, {
      onDelete: 'restrict',
    }),
    ...timestamps(),
  },
  (table) => [
    check(
      'account_setup_purpose_valid',
      sql`${table.purpose} in ('activation', 'reset')`,
    ),
  ],
)

/** Immutable access audit history. Every privileged change is committed together with its audit record; no secrets are stored. */
export const accessAudit = pgTable('access_audit', {
  /** PostgreSQL-generated time-ordered audit identifier. */
  id: uuidv7PrimaryKey(),
  /** Acting account; null identifies an operator-only bootstrap or owner recovery. */
  actorId: text('actor_id').references(() => user.id, { onDelete: 'restrict' }),
  /** Account whose access changed; history cannot be cascade-deleted with a user. */
  targetId: text('target_id')
    .notNull()
    .references(() => user.id, { onDelete: 'restrict' }),
  /** Stable action identifier such as account.activated or account.suspended. */
  action: text('action').notNull(),
  /** Required administrative reason or a fixed description of a self-service activation/reset. */
  reason: text('reason').notNull(),
  ...timestamps(),
})
